mapper.update:
UPDATE budget_account
SET reserved_amount = reserved_amount - #{reservedDecrement},
    settled_amount = settled_amount + #{actualAmount},
    updated_at = now()
WHERE tenant_id = #{tenantId}::uuid AND currency = #{currency}
  AND reserved_amount  >=  #{reservedDecrement}

UPDATE budget_account
SET reserved_amount = reserved_amount - #{amount}, updated_at = now()
WHERE tenant_id = #{tenantId}::uuid AND currency = #{currency}
  AND reserved_amount  >=  #{amount}

UPDATE budget_reservation
SET state = 'RELEASED', release_reason = #{reason}
WHERE tenant_id = #{tenantId}::uuid AND reservation_id = #{reservationId}::uuid
